const input = $input.first().json;
if (!input.headers?.['x-workflow-token'] || input.headers['x-workflow-token'] !== $env.N8N_WEBHOOK_TOKEN) throw new Error('Unauthorized workflow trigger.');
const body = input.body ?? {};
for (const key of ['work_item_key', 'workflow_key', 'workflow_version']) { if (!body[key]) throw new Error(`Missing ${key}.`); }
return [{ json: body }];

const raw=$input.first().json.output ?? {};
const clauses=Array.isArray(raw.clauses)?raw.clauses:[];
if (!clauses.length) throw new Error('Planner omitted customer requests.');
const normalized=clauses.map((c,i)=>{const text=[c?.text,c?.customer_text].find(v=>typeof v==='string'&&v.trim());if(!text)throw new Error('Planner omitted clause text.');return {...c,text:text.trim(),id:'request_'+(i+1)};});
return [{json:{output:{...raw,clauses:normalized,unsupported_requests:Array.isArray(raw.unsupported_requests)?raw.unsupported_requests:[]}}}];

