const raw=$input.first().json.output??{};
const candidate=$('Generate Ticket Draft').first().json.output??{};
const prepared=$('Prepare Ticket Generation').first().json;
const answer=[candidate.answer_customer_language,candidate.answer_en].find(v=>typeof v==='string'&&v.trim())??'';
const checks=["factual_accuracy", "operator_decision", "action_stage", "template_applicability", "intent_coverage", "actionable_guidance", "natural_tone", "customer_appropriateness", "language_equivalence"];
const valid=typeof raw.approved==='boolean'&&typeof raw.must_block==='boolean'&&raw.reviewed_answer===answer&&Array.isArray(raw.covered_request_ids)&&Array.isArray(raw.business_conflicts)&&Array.isArray(raw.guidance_conflicts);
const allChecks=checks.every(k=>raw.quality_checks?.[k]===true);
const ids=prepared.plan.clauses.map(c=>c.id);
const coverage=ids.every(id=>(raw.covered_request_ids??[]).includes(id));
const guidance=prepared.operator_guidance?.text;
const guidanceOk=!guidance||(typeof raw.guidance_evidence==='string'&&raw.guidance_evidence.trim()&&guidance.includes(raw.guidance_evidence)&&raw.guidance_conflicts?.length===0);
const planOk=prepared.reply_plan.blocking_reasons.length===0;
const decisionOk=!prepared.reply_plan.case_progress||(raw.response_decision_approved===true&&raw.reviewed_response_mode===prepared.reply_plan.response_decision?.mode);
const approved=decisionOk&&valid&&raw.approved===true&&raw.must_block===false&&allChecks&&coverage&&guidanceOk&&planOk&&raw.business_conflicts.length===0;
return [{json:{output:{...raw,approved,must_block:!valid||raw.must_block===true||!guidanceOk||!planOk,
covered_intents:prepared.plan.clauses.filter(c=>(raw.covered_request_ids??[]).includes(c.id)).map(c=>c.intent),
final_answer:answer,answer_en:candidate.answer_en??answer,answer_customer_language:answer,
safety_flags:Array.isArray(raw.safety_flags)?raw.safety_flags.filter(v=>typeof v==='string'):[],
repairable:valid&&!approved&&raw.repairable===true&&raw.must_block===false&&planOk&&raw.business_conflicts.length===0&&raw.guidance_conflicts.length===0,candidate,initial_review:null}}}];

